//Credits
//Most of thd code either mine or heavily edited
//Inigo Quilez - https://iquilezles.org/articles/distfunctions/
//Simon Dev - https://youtu.be/BNZtUB7yhX4?si=BYa0fFE8p94YxVNp
//Kishimisu - https://youtu.be/khblXafu7iA?si=BrkA9si53tEGV13e

//Global vars
const int obj=3;
int steps=255;
float renderDist=100.;
vec3 skyColor = vec3(0.2,0.4,1);
bool ortho = false; //Joke setting

//Sphere - Inigo Quilez https://iquilezles.org/articles/distfunctions/
float sdPie(vec3 p, float s) {
    return length(p)-s;
}

//Rounded cube - Inigo Quilez https://iquilezles.org/articles/distfunctions/
float sdBox(vec3 p, vec3 b, float r) {
  vec3 q = abs(p) - b + r;

  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0) - r;
}

//“Terrain” - by me this time :)
float sdFloor(vec3 p) {
    return p.y;
}

vec2 minD(float [obj] array) {
    int i;
    float m = renderDist+1.;
    float sm = m;

    int iter;
    for (i=0; i<array.length(); i++) {
        m = min(m,array[i]);
        if (m<sm) {sm=m; iter=i;}
    }
    return vec2(sm,iter);
}

float [4] map(vec3 p) {
    vec3 [obj] C;
    C[0] = vec3(1,0.2,0.1);
    C[1] = vec3(0.2,0.9,0.9);
    C[2] = vec3(1);
    vec3 [obj] P;
    P[0] = vec3(sin(iTime*2.)*6.,0,5);
    P[1] = vec3(sin(iTime)*3.,cos(iTime)*3.,3);
    P[2] = vec3(-2);
    float [obj] SD;
    SD[0] = sdPie(p-P[0],1.);
    SD[1] = sdBox(p-P[1],vec3(1),0.5);
    SD[2] = sdFloor(p-P[2]);

    vec2 m = minD(SD);

    float [4] ar;
    ar[0] = m.x;
    ar[1] = C[int(m.y)].r;
    ar[2] = C[int(m.y)].g;
    ar[3] = C[int(m.y)].b;
    return ar;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Pixel coordinates (from -1 to 1)
    vec2 uv = (fragCoord*2.-iResolution.xy)/iResolution.y;

    // Time varying pixel color
    //vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    vec3 ro = vec3(0,0,-3);
    vec3 rd = normalize(vec3(uv,1));
    if (ortho) {
        ro = vec3(uv,-3);
        rd = normalize(vec3(0,0,1));
    }

    bool isSky = false;

    vec4 col = vec4(vec3(0.5),1);

    int i;
    float t=0.;
    for (i=0; i<steps; i++) {
        vec3 pos = ro + rd * t;

        float [4] mD = map(pos);

        float d = mD[0];

        t+=d;

        if (d<0.01) {
            col = vec4(vec3(mD[1],
            mD[2],
            mD[3]),1);
            break;
        }
        if (t>renderDist) {
            isSky = true;
            break;
        }
    }
    if (isSky) col = vec4(skyColor,1);
    //col += vec4(i)/float(steps); Joke, adds in a "bloom" effect
    //Output to screen
    fragColor = vec4(col);
}
